from pathlib import Path
p=Path('/home/ubuntu/projects/depthwizard-b61638c4/index.html')
s=p.read_text()
css='''
.immersive-panel{background:rgba(17,27,25,.94);border:1px solid #385242;box-shadow:0 20px 55px #0003}.dim-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.dim-btn{background:#ffffff06;border:1px solid var(--line);color:var(--muted);padding:9px 8px;text-align:left;font-size:10px}.dim-btn.on{border-color:#caff5a88;color:var(--lime);background:#caff5a12}.compare{height:150px;position:relative;overflow:hidden;background:#0a1110}.compare img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.compare .after{clip-path:inset(0 0 0 50%)}.compare-line{position:absolute;top:0;bottom:0;left:50%;width:1px;background:var(--lime);box-shadow:0 0 14px var(--lime)}.compare-handle{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:24px;height:24px;border:1px solid var(--lime);border-radius:50%;background:#09100f;color:var(--lime);display:grid;place-items:center;font-size:11px}.atmosphere-note{font-size:10px;color:var(--muted);line-height:1.5}.motion-toggle{display:flex;align-items:center;gap:7px;font-size:10px;color:var(--muted)}.motion-toggle input{accent-color:var(--lime)}
@media(max-width:700px){.dim-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
'''
s=s.replace('</style></head>',css+'</style></head>',1)
marker='<div class="grid grid-cols-2 md:grid-cols-4 gap-3">'
extra='''<div id="immersivePanel" class="immersive-panel rounded-2xl p-5 mb-5"><div class="flex flex-wrap items-center justify-between gap-3 mb-4"><div><div class="eyebrow">02B / 8D immersive controls</div><div class="text-sm font-bold mt-1">Eight motion dimensions. One stable subject.</div></div><div class="flex items-center gap-3"><label class="motion-toggle"><input id="deviceMotion" type="checkbox"> Device motion</label><span id="deviceMotionState" class="mono text-[10px] text-[#879890]">OPTIONAL</span></div></div><div class="dim-grid mb-4"><button class="dim-btn on" data-dim="depth">01 · Forward / back</button><button class="dim-btn on" data-dim="lateral">02 · Left / right</button><button class="dim-btn on" data-dim="vertical">03 · Up / down</button><button class="dim-btn on" data-dim="orbit">04 · Orbit</button><button class="dim-btn on" data-dim="perspective">05 · Perspective</button><button class="dim-btn on" data-dim="parallax">06 · Parallax</button><button class="dim-btn on" data-dim="cinematic">07 · Cinematic sway</button><button class="dim-btn on" data-dim="atmosphere">08 · Atmosphere / light</button></div><div class="grid grid-cols-1 md:grid-cols-[1fr_1fr] gap-4"><div><div class="eyebrow mb-2">Before / after depth comparison</div><div id="compare" class="compare rounded-lg"><img id="compareBefore"><img id="compareAfter" class="after"><div class="compare-line"></div><div class="compare-handle">↔</div></div><input id="compareRange" type="range" min="15" max="85" value="50" class="w-full mt-2"></div><div class="panel-soft rounded-lg p-4"><div class="eyebrow mb-2">Scene recipe</div><div class="atmosphere-note">The viewer builds far, middle, and foreground planes from the original frame, then applies depth-weighted parallax, perspective shift, soft subject shadow, light falloff, and atmospheric particles. The person layer remains an identity-preserving alpha cutout.</div><div class="mono text-[10px] text-[#caff5a] mt-3">FAR → MID → PERSON → CAMERA</div></div></div></div>'''
s=s.replace(marker,extra+marker,1)
start=s.index('// --- 2.5D depth flythrough')
end=s.index('</script></body></html>',start)
js=r'''// --- 8D immersive depth experience -----------------------------------------
let fly={canvas:null,ctx:null,bg:null,person:null,depth:null,ready:false,playing:false,lighting:true,parallax:1,x:0,y:0,z:1,yaw:0,pitch:0,lastX:0,lastY:0,drag:false,raf:0,started:0,device:false,motionX:0,motionY:0,dims:{depth:true,lateral:true,vertical:true,orbit:true,perspective:true,parallax:true,cinematic:true,atmosphere:true}};
function flyLoad(url){return new Promise((resolve,reject)=>{const i=new Image();i.crossOrigin='anonymous';i.onload=()=>resolve(i);i.onerror=reject;i.src=url})}
async function initFlythrough(result){try{fly.bg=await flyLoad(result.assets.original_url);fly.person=await flyLoad(result.assets.cutout_url);fly.depth=await flyLoad(result.assets.depth_map_url);fly.canvas=$('flyCanvas');fly.ctx=fly.canvas.getContext('2d');fly.ready=true;$('flyMode').textContent='8D SCENE · 4 LAYERS READY';$('flyMode').style.color='var(--lime)';$('compareBefore').src=result.assets.original_url;$('compareAfter').src=result.assets.cutout_url;flyReset();flyResize();if(!fly.raf)fly.raf=requestAnimationFrame(flyFrame);log('8D scene assembled · far / mid / person / camera layers')}catch(e){$('flyMode').textContent='IMMERSIVE SCENE UNAVAILABLE';log('8D scene error: '+e.message)}}
function flyResize(){if(!fly.canvas)return;const r=fly.canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);fly.canvas.width=Math.max(1,Math.floor(r.width*d));fly.canvas.height=Math.max(1,Math.floor(r.height*d));fly.ctx.setTransform(d,0,0,d,0,0)}
function flyReset(){fly.x=0;fly.y=0;fly.z=1;fly.yaw=0;fly.pitch=0;fly.started=performance.now();flyUpdateHud()}
function flyUpdateHud(){$('flyPose').textContent=`X ${fly.x.toFixed(2)} / Y ${fly.y.toFixed(2)} / Z ${fly.z.toFixed(2)}`;$('flyParallax').textContent=fly.parallax.toFixed(1)+'×';$('flyProgress').style.width=(((performance.now()-fly.started)%9000)/9000*100)+'%'}
function fitImage(ctx,img,w,h,scale=1,dx=0,dy=0){const ratio=Math.max(w/img.width,h/img.height)*scale;const iw=img.width*ratio,ih=img.height*ratio;ctx.drawImage(img,(w-iw)/2+dx,(h-ih)/2+dy,iw,ih)}
function layer(ctx,img,w,h,scale,dx,dy,alpha=1){ctx.save();ctx.globalAlpha=alpha;fitImage(ctx,img,w,h,scale,dx,dy);ctx.restore()}
function flyFrame(t){fly.raf=requestAnimationFrame(flyFrame);if(!fly.ready)return;const c=fly.canvas,ctx=fly.ctx,w=c.clientWidth,h=c.clientHeight;const elapsed=(t-fly.started);if(fly.playing){if(fly.dims.cinematic)fly.x=Math.sin(elapsed/2600)*.16;if(fly.dims.vertical)fly.y=Math.cos(elapsed/3300)*.07;if(fly.dims.depth)fly.z=1+Math.sin(elapsed/2100)*.045;if(fly.dims.orbit)fly.yaw=Math.sin(elapsed/2800)*.035;if(fly.dims.perspective)fly.pitch=Math.cos(elapsed/3200)*.018;flyUpdateHud()}ctx.clearRect(0,0,w,h);ctx.fillStyle='#06100d';ctx.fillRect(0,0,w,h);const zoom=1/fly.z,px=fly.x*w,py=fly.y*h;const orbitX=fly.dims.orbit?fly.yaw*w:0,orbitY=fly.dims.orbit?fly.pitch*h:0;layer(ctx,fly.bg,w,h,zoom*.965,px*.28-orbitX*.25,py*.28-orbitY*.25,.96);layer(ctx,fly.bg,w,h,zoom*.985,px*.55-orbitX*.55,py*.55-orbitY*.55,.62);if(fly.lighting)layer(ctx,fly.bg,w,h,zoom,px-orbitX,py-orbitY,.36);const subjectX=px-(fly.dims.parallax?fly.yaw*w*1.5*fly.parallax:0),subjectY=py-(fly.dims.parallax?fly.pitch*h*1.5*fly.parallax:0);layer(ctx,fly.person,w,h,zoom*1.012,subjectX,subjectY,.99);if(fly.lighting&&fly.dims.atmosphere){const shadow=ctx.createRadialGradient(w*.5+subjectX*.2,h*.78+subjectY*.2,2,w*.5+subjectX*.2,h*.78+subjectY*.2,w*.3);shadow.addColorStop(0,'rgba(0,0,0,.26)');shadow.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=shadow;ctx.fillRect(0,0,w,h);const glow=ctx.createRadialGradient(w*(.45+fly.x),h*(.3+fly.y),10,w*.5,h*.5,Math.max(w,h)*.8);glow.addColorStop(0,'rgba(202,255,90,.12)');glow.addColorStop(.5,'rgba(118,228,210,.035)');glow.addColorStop(1,'rgba(0,0,0,.38)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);for(let i=0;i<18;i++){const sx=(i*83+(elapsed*.012*(i%3+1)))%w,sy=(i*47+(elapsed*.006*(i%4+1)))%h;ctx.fillStyle=`rgba(202,255,90,${.025+(i%3)*.015})`;ctx.fillRect(sx,sy,1,1)}}ctx.strokeStyle='rgba(202,255,90,.30)';ctx.beginPath();ctx.moveTo(w/2-24,h/2);ctx.lineTo(w/2+24,h/2);ctx.moveTo(w/2,h/2-24);ctx.lineTo(w/2,h/2+24);ctx.stroke()}
function flyToggle(){if(!fly.ready)return toast('Run an analysis first');fly.playing=!fly.playing;$('flyPlay').textContent=fly.playing?'Ⅱ Pause flythrough':'▶ Play flythrough';$('flyMode').textContent=fly.playing?'8D CINEMATIC PLAYBACK':'8D MANUAL CAMERA';if(fly.playing)fly.started=performance.now()}
$('flyPlay').onclick=flyToggle;$('flyReset').onclick=()=>{flyReset();toast('8D camera reset')};$('flyLight').onclick=()=>{fly.lighting=!fly.lighting;$('flyLightState').textContent=fly.lighting?'ON':'OFF'};$('flyParallaxRange').oninput=e=>{fly.parallax=+e.target.value;flyUpdateHud()};$('flyFullscreen').onclick=()=>{$('flyWrap').requestFullscreen?.()||toast('Fullscreen is not supported in this browser')};document.querySelectorAll('.dim-btn').forEach(b=>b.onclick=()=>{const k=b.dataset.dim;fly.dims[k]=!fly.dims[k];b.classList.toggle('on',fly.dims[k]);toast(k+' motion '+(fly.dims[k]?'enabled':'disabled'))});$('compareRange').oninput=e=>{const v=e.target.value;$('compareAfter').style.clipPath=`inset(0 0 0 ${v}%)`;$('compareLine').style.left=v+'%';document.querySelector('.compare-line').style.left=v+'%';document.querySelector('.compare-handle').style.left=v+'%'};$('flyWrap').addEventListener('pointerdown',e=>{if(!fly.ready)return;fly.drag=true;fly.lastX=e.clientX;fly.lastY=e.clientY;fly.playing=false;$('flyPlay').textContent='▶ Play flythrough';$('flyMode').textContent='8D MANUAL CAMERA';$('flyWrap').setPointerCapture?.(e.pointerId)});$('flyWrap').addEventListener('pointermove',e=>{if(!fly.drag)return;const dx=e.clientX-fly.lastX,dy=e.clientY-fly.lastY;fly.yaw+=(fly.dims.orbit?dx*.0015:0);fly.pitch=Math.max(-.3,Math.min(.3,fly.pitch+(fly.dims.perspective?dy*.0015:0)));if(fly.dims.lateral)fly.x=Math.max(-.35,Math.min(.35,fly.x+dx/800));if(fly.dims.vertical)fly.y=Math.max(-.25,Math.min(.25,fly.y+dy/800));fly.lastX=e.clientX;fly.lastY=e.clientY;flyUpdateHud()});['pointerup','pointercancel','pointerleave'].forEach(e=>$('flyWrap').addEventListener(e,()=>fly.drag=false));$('flyWrap').addEventListener('wheel',e=>{e.preventDefault();if(fly.dims.depth)fly.z=Math.max(.72,Math.min(1.35,fly.z+e.deltaY*.0008));flyUpdateHud()},{passive:false});window.addEventListener('keydown',e=>{if(!fly.ready)return;const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown','a','d','w','s'].includes(k)){e.preventDefault();if((k==='arrowleft'||k==='a')&&fly.dims.lateral)fly.x-=.035;if((k==='arrowright'||k==='d')&&fly.dims.lateral)fly.x+=.035;if((k==='arrowup'||k==='w')&&fly.dims.vertical)fly.y-=.035;if((k==='arrowdown'||k==='s')&&fly.dims.vertical)fly.y+=.035;fly.x=Math.max(-.35,Math.min(.35,fly.x));fly.y=Math.max(-.25,Math.min(.25,fly.y));flyUpdateHud()}if(k==='r'&&document.activeElement?.tagName!=='INPUT')flyReset()});$('deviceMotion').onchange=async e=>{if(!e.target.checked){fly.device=false;$('deviceMotionState').textContent='OPTIONAL';return}try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){const p=await DeviceOrientationEvent.requestPermission();if(p!=='granted')throw Error('permission denied')}window.addEventListener('deviceorientation',ev=>{if(fly.device)return;fly.motionX=(ev.gamma||0)/90;fly.motionY=(ev.beta||0)/180;fly.x=fly.motionX*.22;fly.y=fly.motionY*.12;flyUpdateHud()});fly.device=true;$('deviceMotionState').textContent='ACTIVE';toast('Device motion enabled')}catch(err){e.target.checked=false;$('deviceMotionState').textContent='UNAVAILABLE';toast('Device motion permission was not granted')}};window.addEventListener('resize',flyResize);
'''
s=s[:start]+js+s[end:]
p.write_text(s)
print('8d patched')
